import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"52、【艮】 艮下艮上","description":"横渠易说 - 52、【艮】 艮下艮上","frontmatter":{"title":"52、【艮】 艮下艮上","description":"横渠易说 - 52、【艮】 艮下艮上"},"headers":[],"relativePath":"zh/classics/hengqu/054.md","filePath":"zh/classics/hengqu/054.md"}'),l={name:"zh/classics/hengqu/054.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_52、【艮】-艮下艮上" tabindex="-1">52、【艮】 艮下艮上 <a class="header-anchor" href="#_52、【艮】-艮下艮上" aria-label="Permalink to “52、【艮】 艮下艮上”">​</a></h1><p>虽处喧閧，亦无害于为学。有人于此，或日月而至焉，亦有终日而不至者，及其久也，去者常少。若居于家，闻婴孩之啼则有不忍之心，闻奴婢喧戾则犹有不容之意，至于市井纷嚣一不与我事，何伤于存诚养志!易曰：“艮其背，不获其身，行其庭，不见其人，无咎。”夫入他人之庭，不见其人可止也，艮其背至近于人也，然且不见，以其上下无应也。“时止则止，时行则行，动静不失其时，其道光明”，学者必时其动静，则其道乃不蔽昧而明白。今人从学之久，不见进长，正以莫识动静，见他人扰扰，非关己事而所修亦废。由圣学观之，冥冥悠悠，以是终身，谓之光明可乎？</p><h3 id="彖曰-艮-止也-时止则止-时行则行-动静不失其时-其道光明。艮其止-止其所也-上下敌应-不相与也-是以不获其身-行其庭-不见其人-无咎也。" tabindex="-1">彖曰：艮，止也，时止则止，时行则行，动静不失其时，其道光明。艮其止，止其所也，上下敌应，不相与也，是以不获其身，行其庭，不见其人，无咎也。 <a class="header-anchor" href="#彖曰-艮-止也-时止则止-时行则行-动静不失其时-其道光明。艮其止-止其所也-上下敌应-不相与也-是以不获其身-行其庭-不见其人-无咎也。" aria-label="Permalink to “彖曰：艮，止也，时止则止，时行则行，动静不失其时，其道光明。艮其止，止其所也，上下敌应，不相与也，是以不获其身，行其庭，不见其人，无咎也。”">​</a></h3><p>［动静不失其时，是时措之宜也，集义也，集义久则自有光明。静则无见，必动乃见。其道光明，以其本之光明，故其发也光明。］ 易言“光明”者，多艮之象，着则明之义也。</p><h3 id="象曰-兼山艮-君子以思不出其位。" tabindex="-1">象曰：兼山艮，君子以思不出其位。 <a class="header-anchor" href="#象曰-兼山艮-君子以思不出其位。" aria-label="Permalink to “象曰：兼山艮，君子以思不出其位。”">​</a></h3><p>位，所安之分也。如“素夷狄行乎夷狄，素患难行乎患难”。</p><h3 id="初六-艮其趾-无咎-利永贞。-象曰-艮其趾-未失正也。" tabindex="-1">初六，艮其趾，无咎，利永贞。 象曰：“艮其趾”，未失正也。 <a class="header-anchor" href="#初六-艮其趾-无咎-利永贞。-象曰-艮其趾-未失正也。" aria-label="Permalink to “初六，艮其趾，无咎，利永贞。 象曰：“艮其趾”，未失正也。”">​</a></h3><h3 id="六二-艮其腓-不拯其随-其心不快。-象曰-不拯其随-未退听也。" tabindex="-1">六二，艮其腓，不拯其随，其心不快。 象曰：“不拯其随”，未退听也。 <a class="header-anchor" href="#六二-艮其腓-不拯其随-其心不快。-象曰-不拯其随-未退听也。" aria-label="Permalink to “六二，艮其腓，不拯其随，其心不快。 象曰：“不拯其随”，未退听也。”">​</a></h3><p>腓，体之随也，不能禁其趾而徒止其腓，腓所未听，故心不能快。</p><h3 id="九三-艮其限-列其夤-厉薰心。-象曰-艮其限-危薰心也。" tabindex="-1">九三，艮其限，列其夤，厉薰心。 象曰：“艮其限”，危薰心也。 <a class="header-anchor" href="#九三-艮其限-列其夤-厉薰心。-象曰-艮其限-危薰心也。" aria-label="Permalink to “九三，艮其限，列其夤，厉薰心。 象曰：“艮其限”，危薰心也。”">​</a></h3><p>一身而动止中列，危至薰心。</p><h3 id="六四-艮其身-无咎。-象曰-艮其身-止诸躬也。" tabindex="-1">六四，艮其身，无咎。 象曰：“艮其身”，止诸躬也。 <a class="header-anchor" href="#六四-艮其身-无咎。-象曰-艮其身-止诸躬也。" aria-label="Permalink to “六四，艮其身，无咎。 象曰：“艮其身”，止诸躬也。”">​</a></h3><p>止于心，故能艮其身，咸之九四“朋从尔思”义近之。</p><h3 id="六五-艮其辅-言有序-悔亡。-象曰-艮其辅-以中正也。" tabindex="-1">六五，艮其辅，言有序，悔亡。 象曰：“艮其辅”，以中正也。 <a class="header-anchor" href="#六五-艮其辅-言有序-悔亡。-象曰-艮其辅-以中正也。" aria-label="Permalink to “六五，艮其辅，言有序，悔亡。 象曰：“艮其辅”，以中正也。”">​</a></h3><p>不能施止于心而能止其言，故悔可亡也。</p><h3 id="上九-敦-艮吉。-象曰-敦艮之吉-以厚终也。" tabindex="-1">上九，敦，艮吉。 象曰：敦艮之吉，以厚终也。 <a class="header-anchor" href="#上九-敦-艮吉。-象曰-敦艮之吉-以厚终也。" aria-label="Permalink to “上九，敦，艮吉。 象曰：敦艮之吉，以厚终也。”">​</a></h3>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
